  5| #define MAX_SIGNALS 32000
  6| #define MAX_DEPS 10000
  7| 
  8| typedef enum {
  9|     OP_CONST_0,
 10|     OP_CONST_1,
 11|     OP_COPY,
 12|     OP_NOT,
 13|     OP_AND,
 14|     OP_OR,
 15|     OP_XOR
 16| } OpType;
 17| 
 18| typedef struct {
 19|     OpType type;
 20|     int src1;
 21|     int src2;
 22| } Gate;
