184| // Track which signals are already in queue
185| char in_queue[MAX_SIGNALS];
186| char next_in_queue[MAX_SIGNALS];
187| char did[MAX_SIGNALS];  // Track which signals have been processed this step
188| int step_number = -1;
189| int *next_queue;
190| int next_queue_size = 0;
191| 
192| void next_heap_push(int signal) {
193|     if (next_queue_size >= MAX_SIGNALS) return;
194|     
195|     // Add to end
196|     next_queue[next_queue_size] = signal;
197|     
198|     // Bubble up
199|     int idx = next_queue_size;
200|     while (idx > 0) {
201|         int parent = (idx - 1) / 2;
202|         if (next_queue[idx] < next_queue[parent]) {
203|             swap(&next_queue[idx], &next_queue[parent]);
204|             idx = parent;
205|         } else {
206|             break;
207|         }
208|     }
209|     next_queue_size++;
210| }
