306|     // Initialize
307|     memset(values, 0, sizeof(values));
308|     memset(num_deps, 0, sizeof(num_deps));
309|     
310|     // Allocate queues
311|     update_queue = malloc(MAX_SIGNALS * sizeof(int));
312|     next_queue = malloc(MAX_SIGNALS * sizeof(int));
313|     if (!update_queue || !next_queue) {
314|         fprintf(stderr, "Failed to allocate queues\n");
315|         return 1;
316|     }
317|     
318|     // Parse gates file
319|     parse_gates("gates.txt");
320| 
